import attr
import logging
from typing import Optional, List
from .connection_details import SshServiceDetails, HttpConnectionDetails

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@attr.s(cmp=False)
class NetAct(object):
    """
    This class defines an instance of NetAct.

    :param Optional[List[SshServiceDetails]] ssh_connection_info: SSH details for NetAct nodes
    :param Optional[HttpConnectionDetails] https_main_info: HTTPS details of NetAct Main URL
    """
    ssh_connections_info = attr.ib(default=None, type=Optional[List[SshServiceDetails]])
    https_main_info = attr.ib(default=None, type=Optional[HttpConnectionDetails])


@attr.s(cmp=False)
class NOM(object):
    """
    This class defines an instance of NOM.

    :param Optional[List[SshServiceDetails]] ssh_connection_info: SSH details of NOM Edge Nodes
    :param Optional[HttpConnectionDetails] https_user_mgmt_info: HTTPS details of User and Role
        Management URL, used for acquiring access and refresh tokens.
    :param Optional[HttpConnectionDetails] https_main_info: HTTPS details of NOM Main URL
    :param Optional[HttpConnectionDetails] https_rest_info: HTTPS details of NOM API GW URL
    :param Optional[str] neo_endpoints_ip: IP address for querying Neo Endpoints.
        Deprecated, configure https_rest_info parameter instead.
    """
    ssh_connections_info = attr.ib(default=None, type=Optional[List[SshServiceDetails]])
    https_user_mgmt_info = attr.ib(default=None, type=Optional[HttpConnectionDetails])
    https_main_info = attr.ib(default=None, type=Optional[HttpConnectionDetails])
    https_rest_info = attr.ib(default=None, type=Optional[HttpConnectionDetails])
    neo_endpoints_ip = attr.ib(default=None, type=Optional[str])

    def __attrs_post_init__(self):
        if self.neo_endpoints_ip is not None:
            logger.warning('NOM.neo_endpoints_ip parameter is deprecated, '
                           'use https_rest_info parameter instead.')


@attr.s(cmp=False)
class NMS(object):
    """
    This class defines an instance of NMS.

    :param str addr: IP ADDRESS or FQDN.
        Deprecated, configure and use NOM or NetAct objects' parameters instead.
    :param Optional[NOM] nom: NOM class instance object
    :param Optional[List[NetAct]] netact: List of NetAct class instance object
    """
    addr = attr.ib(default=None, type=Optional[str])
    nom = attr.ib(default=None, type=Optional[NOM])
    netact = attr.ib(default=None, type=Optional[List[NetAct]])

    def __attrs_post_init__(self):
        if self.addr is not None:
            logger.warning('NMS.addr parameter is deprecated, '
                           'use NOM or NetAct objects parameters instead.')


@attr.s(cmp=False)
class Netact(NMS):
    """
    Deprecated, use NetAct class instead.
    """

    def __attrs_post_init__(self):
        logger.warning('Netact class is deprecated, use NetAct class instead.')
